import assert from 'node:assert/strict';
import { test } from 'node:test';
import { nearbyStores } from '../nearby.js';

test('nearbyStores: within the limit, nearest first, and a store exactly at the limit counts', () => {
  const stores = [{ id: 'c', km: 9 }, { id: 'b', km: 5 }, { id: 'a', km: 2 }];
  assert.deepEqual(nearbyStores(stores, 5).map((s) => s.id), ['a', 'b']);
});

